mapper.select:
SELECT authority_code AS authorityCode, authority_nm AS authorityNm, authority_dc AS authorityDc, authority_level AS authorityLevel, tenant_scoped AS tenantScoped, use_at AS useAt, created_at AS frstRegistPnttm, 'SYSTEM' AS frstRegisterId, updated_at AS lastUpdtPnttm, 'SYSTEM' AS lastUpdusrId FROM tb_authorityinfo WHERE 1=1
AND use_at = #{useAt}
AND authority_code ILIKE '%' || #{searchKeyword} || '%'
AND authority_nm ILIKE '%' || #{searchKeyword} || '%'
AND authority_dc ILIKE '%' || #{searchKeyword} || '%'
ORDER BY authority_level, authority_code OFFSET #{firstIndex} LIMIT #{recordCountPerPage}

WITH RECURSIVE menu_tree AS ( SELECT m.menu_id, m.parent_menu_id, m.menu_nm, m.menu_ordr, lpad(coalesce(m.menu_ordr, 0)::text, 5, '0') AS sort_path, 1 AS depth FROM tb_menu_info m WHERE m.parent_menu_id IS NULL UNION ALL SELECT c.menu_id, c.parent_menu_id, c.menu_nm, c.menu_ordr, mt.sort_path || '-' || lpad(coalesce(c.menu_ordr, 0)::text, 5, '0') AS sort_path, mt.depth + 1 FROM tb_menu_info c INNER JOIN menu_tree mt ON c.parent_menu_id = mt.menu_id ) SELECT rmp.rmp_id AS roleMenuId, rmp.authority_code AS authorityCode, rmp.menu_id AS menuId, rmp.permission_id AS permissionId, rmp.use_at AS useAt, rmp.crt_dt AS frstRegistPnttm, rmp.crt_id AS frstRegisterId, rmp.upd_dt AS lastUpdtPnttm, rmp.upd_id AS lastUpdusrId, a.authority_nm AS authorityNm, mt.menu_nm AS menuNm, m.menu_url AS menuUrl, p.permission_nm AS permissionNm, p.permission_level AS permissionLevel FROM tb_role_menu_permission rmp LEFT JOIN tb_authorityinfo a ON rmp.authority_code = a.authority_code LEFT JOIN menu_tree mt ON rmp.menu_id = mt.menu_id LEFT JOIN tb_menu_info m ON rmp.menu_id = m.menu_id LEFT JOIN tb_permission_type p ON rmp.permission_id = p.permission_id WHERE rmp.use_at = 'Y'
AND rmp.authority_code = #{authorityCode}
AND rmp.menu_id = #{menuId}
AND rmp.permission_id = #{permissionId}
ORDER BY mt.sort_path
